        if(!$licenses)echo '<p>No issued software licenses yet.</p>';
        echo '</div><h2>Purchased downloads</h2>';
        $canSoftwareDownloads=!$review&&contact_can('downloads');
        $assets=$canSoftwareDownloads?all('SELECT a.id,a.sku,a.version,a.title,a.released_at,l.id AS license_id,e.invoice_id,e.unit_number FROM '.table('software_assets').' a JOIN '.table('website_licenses').' l ON l.product_id=a.sku JOIN '.table('software_entitlements').' e ON e.license_id=l.id WHERE l.customer_id=? AND l.is_active=1 AND l.is_master=0 AND a.is_published=1 AND a.released_at IS NOT NULL AND (e.expires_at IS NULL OR e.expires_at>UTC_TIMESTAMP()) AND (e.updates_until IS NULL OR a.released_at<=e.updates_until) ORDER BY a.sku,a.released_at DESC,a.id DESC,(e.invoice_id IS NULL),l.id LIMIT 250',[$clientId]):[];
        $shown=[];$downloadCount=0;
        foreach($assets as $asset){
            if(isset($shown[(int)$asset['id']]))continue;
            if(!software_asset_entitlement_authorized($clientId,(int)$asset['license_id'],$asset))continue;
            $shown[(int)$asset['id']]=true;$downloadCount++;
            $source=(int)($asset['invoice_id']??0)>0
                ?' · purchase #'.(int)$asset['invoice_id'].(($asset['unit_number']??null)!==null?' · unit '.(int)$asset['unit_number']:'')
                :' · owner-issued license #'.(int)$asset['license_id'];
            echo '<p><a href="'.esc(site_url('api/software-download.php?id='.$asset['id'].'&license='.$asset['license_id'])).'">'.esc($asset['title'].' · v'.$asset['version']).' — Download ZIP</a>'.esc($source).'</p>';
        }
        if($downloadCount===0)echo $canSoftwareDownloads?'<p>No eligible software downloads yet.</p>':'<p>Your contact permissions do not include downloads.</p>';
        echo '<h2>Software orders and invoices</h2>';
        $orders=all('SELECT o.*,i.status,i.amount_cents,i.reference FROM '.table('software_orders').' o JOIN '.table('studio_invoices').' i ON i.id=o.invoice_id WHERE o.client_id=? ORDER BY o.id DESC LIMIT 100',[$clientId]);
        foreach($orders as $order){
            echo '<article class="workspace-card"><h3>'.esc($order['sku']).' · '.esc($order['reference']).'</h3>';
            echo '<p>Domain: '.esc($order['domain']).' · '.esc($order['status']);
            echo ' · $'.esc(number_format((int)$order['amount_cents']/100,2));
            echo ' · <a href="'.esc(studio_url(['invoice'=>$order['invoice_id']])).'">Invoice</a></p>';
            if(in_array($order['billing_term'],['month','year'],true)){
                $renewals=all('SELECT i.id,i.reference,i.status,i.amount_cents,i.paid_at FROM '.table('software_subscription_receipts').' r JOIN '.table('studio_invoices').' i ON i.id=r.invoice_id WHERE r.subscription_invoice_id=? AND r.invoice_id<>r.subscription_invoice_id ORDER BY r.id DESC LIMIT 36',[$order['invoice_id']]);
                if($renewals){
                    echo '<h4>Renewal invoices</h4><ul>';
                    foreach($renewals as $renewal){
                        echo '<li>'.esc($renewal['reference']).' · '.esc($renewal['status']).' · $'.esc(number_format((int)$renewal['amount_cents']/100,2));
                        if($renewal['paid_at']!==null)echo ' · paid '.esc($renewal['paid_at']).' UTC';
                        echo ' · <a href="'.esc(studio_url(['invoice'=>$renewal['id']])).'">Invoice</a></li>';
                    }
                    echo '</ul>';
                }
                $sub=one('SELECT status,gateway_subscription_id FROM '.table('software_subscriptions').' WHERE invoice_id=?',[$order['invoice_id']]);
                if($sub){
                    $invoicePaid=(string)$order['status']==='paid';
                    $subscriptionLabel=match((string)$sub['status']){
                        'creating'=>'Enrollment pending · software remains locked until verified payment',
                        'pending_first_payment'=>'Awaiting first verified payment · software remains locked',
                        'active'=>'Active recurring billing',
                        'payment_failed'=>$invoicePaid
                            ?'Payment failed · paid-through access remains until license expiry'
                            :'Payment failed · software remains locked until payment is verified',
                        'billing_suspended'=>$invoicePaid
                            ?'Billing suspended · access resumes automatically after verified payment'
                            :'Billing suspended · software remains locked until payment is verified',
                        'cancelling'=>$invoicePaid
                            ?'Cancellation pending · paid-through access remains until license expiry'
                            :'Cancellation pending · software remains locked until verified payment',
                        'cancelled'=>$invoicePaid
                            ?'Cancelled · paid-through access remains until license expiry'
                            :'Cancelled · no paid software access was granted',
                        'review'=>$invoicePaid
                            ?'Billing review · paid-through access remains until current license expiry'
                            :'Billing review · software remains locked until payment is reconciled',
                        'sandbox_test'=>'Sandbox test only · no paid access',
                        'awaiting_gateway_setup'=>$invoicePaid
                            ?'Gateway enrollment pending · current paid-through access remains recorded'
                            :'Gateway enrollment pending · software remains locked',
                        default=>'Billing status: '.(string)$sub['status'],
                    };
                    echo '<p class="hint">Subscription: '.esc($subscriptionLabel).'</p>';
                }
                if($canPurchase && $sub && in_array($sub['status'],['pending_first_payment','active','payment_failed','billing_suspended','sandbox_test'],true)){
                    echo '<form method="post">'.support_csrf_field();
                    echo '<input type="hidden" name="action" value="software_subscription_cancel">';
                    echo '<input type="hidden" name="invoice_id" value="'.(int)$order['invoice_id'].'">';
                    echo '<p class="hint">Cancellation stops future gateway charges; already-paid license access continues through its paid period.</p>';
                    echo '<button class="btn outline" type="submit">Cancel future renewal payments</button></form>';
                }
            }
            if($canPurchase && $order['status']==='issued' && $gateway && $gateway['client_key']!==''){
                $recurring=in_array($order['billing_term'],['month','year'],true);
                $prior=$recurring?
                    one('SELECT status FROM '.table('software_subscriptions').' WHERE invoice_id=?',[$order['invoice_id']]):
                    one('SELECT status FROM '.table('software_charges').' WHERE invoice_id=?',[$order['invoice_id']]);
                $retryable=!$recurring&&$prior&&in_array($prior['status'],['declined','sandbox_test'],true);
                if($prior&&!$retryable){
                    echo '<p class="notice info">Payment status: '.esc($prior['status']).'. Contact billing before attempting another charge.</p>';
                }else{
                    if($retryable)echo '<p class="notice info">Previous '.esc($prior['status']).' attempt is closed. You may submit a fresh card token for this invoice.</p>';
                    echo '<form method="post" data-authorize-net data-login="'.esc($gateway['login']).'" data-client-key="'.esc($gateway['client_key']).'">';
                    echo support_csrf_field();
                    echo '<input type="hidden" name="action" value="'.($recurring?'software_subscription_enroll':'software_charge').'">';
                    echo '<input type="hidden" name="invoice_id" value="'.(int)$order['invoice_id'].'">';
                    echo '<input type="hidden" name="request_key" value="'.bin2hex(random_bytes(32)).'">';
                    echo '<input type="hidden" name="descriptor"><input type="hidden" name="payment_token">';
                    echo '<label>Card number<input data-card-number autocomplete="cc-number" inputmode="numeric" minlength="13" maxlength="23" required></label>';
                    echo '<label>Expiration month (MM)<input data-card-month autocomplete="cc-exp-month" inputmode="numeric" pattern="[0-9]{2}" maxlength="2" required></label>';
                    echo '<label>Expiration year (YY)<input data-card-year autocomplete="cc-exp-year" inputmode="numeric" pattern="[0-9]{2}" maxlength="2" required></label>';
                    echo '<label>Security code<input data-card-code autocomplete="cc-csc" inputmode="numeric" minlength="3" maxlength="4" required></label>';
                    echo '<p class="hint">Card details are sent directly to Authorize.net for tokenization and are not included in this form submission.</p>';
                    if($recurring)echo '<p class="hint">Your '.esc($order['billing_term']).' subscription bills on the gateway schedule. Creating a subscription does not authorize software until its first charge succeeds.</p>';
                    if($gateway['mode']==='sandbox')echo '<p class="notice info">Sandbox test only. This cannot settle a real invoice or issue a paid license.</p>';
                    echo '<p role="alert" data-payment-error></p>';
                    echo '<button class="btn gold" type="submit">'.($recurring?'Enroll in recurring billing':'Pay invoice securely').'</button></form>';
                }
            }elseif($order['status']==='issued'&&$canPurchase){
                echo '<p class="hint">Online card checkout is currently disabled. Your invoice remains available.</p>';
            }
            echo '</article>';
        }
        if($canPurchase){echo '<h2>Purchase software</h2>';
        foreach(catalog_public() as $offer){
            if(!software_order_offer($offer))continue;
            $policy=software_product_policy((int)$offer['id']);
            echo '<article class="workspace-card"><h3>'.esc($offer['title']).'</h3><p>'.esc($offer['summary']).'</p>';
            echo '<p>$'.esc(number_format((int)$offer['amount_cents']/100,2)).' · '.esc(catalog_terms()[$offer['term']]).'</p>';
            echo '<p class="hint">Licensing: '.((int)$policy['update_months']===0?'updates while the license remains valid':(int)$policy['update_months'].' months of updates from issue');
            echo ' · up to '.(int)$policy['max_installations'].' concurrent installation'.((int)$policy['max_installations']===1?'':'s').' per license.</p>';
            if($policy['module_key']!=='')echo '<p class="hint">Module: <code>'.esc($policy['module_key']).'</code></p>';
            if($policy['dependency_skus'])echo '<p class="hint">Product dependencies: '.esc(implode(', ',$policy['dependency_skus'])).'. Review these requirements before purchase.</p>';
            echo '<form method="post">'.support_csrf_field().'<input type="hidden" name="action" value="software_order_buy">';
            echo '<input type="hidden" name="product_id" value="'.(int)$offer['id'].'">';
            echo '<input type="hidden" name="revision" value="'.(int)$offer['revision'].'">';
            echo '<input type="hidden" name="policy_revision" value="'.(int)$policy['revision'].'">';
            echo '<input type="hidden" name="request_key" value="'.bin2hex(random_bytes(32)).'">';
            echo '<label>Installation domain<input name="domain" maxlength="253" required placeholder="example.com"></label>';
            echo '<label>Licenses<input name="quantity" type="number" min="1" max="25" value="1" required></label>';
            if($offer['term']!=='once')echo '<label><input name="subscribe" type="checkbox" value="1" required> I authorize the '.esc($offer['term']).' subscription and understand recurring charges and cancellation terms.</label>';
            echo '<button class="btn gold" type="submit">Create invoice</button></form></article>';
        }
        }
    }
    echo '</div></section>';
    if($gateway){
        $external=$gateway['mode']==='sandbox'?'https://jstest.authorize.net/v1/Accept.js':'https://js.authorize.net/v1/Accept.js';
        echo '<script nonce="'.nonce().'" defer src="'.esc($external).'"></script>';
        echo '<script nonce="'.nonce().'" defer src="'.esc(site_url('assets/js/authorize-net-checkout.js')).'"></script>';
    }
    site_foot(false);
    exit;
}

